CREATE OR REPLACE FUNCTION public.edu_attendance_can_read_course(p_tenant_id uuid, p_course_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid;
  v_role text;
  v_product text;
  v_status text;
  v_branch uuid;
  v_count bigint;
BEGIN
  IF current_setting('role', true) IS DISTINCT FROM 'authenticated' THEN
    RETURN false;
  END IF;
  v_actor := auth.uid();
  IF v_actor IS NULL OR p_tenant_id IS NULL OR p_course_id IS NULL THEN
    RETURN false;
  END IF;
  SELECT u.role, t.product_key INTO v_role, v_product
  FROM public.users u
  JOIN public.tenants t ON t.id = u.tenant_id
  WHERE u.id = v_actor AND u.tenant_id = p_tenant_id AND u.status = 'active' AND t.status = 'active';
  IF NOT FOUND OR v_product IS NULL THEN
    RETURN false;
  END IF;
  SELECT c.status INTO v_status
  FROM public.edu_courses c
  WHERE c.id = p_course_id AND c.tenant_id = p_tenant_id;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  IF v_product <> 'bella_preschool' THEN
    RETURN true;
  END IF;
  IF v_role <> 'admin' OR v_status <> 'active' THEN
    RETURN false;
  END IF;
  SELECT count(*), (array_agg(a.branch_id))[1] INTO v_count, v_branch
  FROM public.preschool_chain_course_branch_assignments a
  WHERE a.tenant_id = p_tenant_id AND a.course_id = p_course_id;
  IF v_count <> 1 OR v_branch IS NULL THEN
    RETURN false;
  END IF;
  RETURN EXISTS(
    SELECT 1 FROM public.org_units b
    JOIN public.user_org_unit_access x ON x.org_unit_id = b.id AND x.tenant_id = b.tenant_id
    WHERE b.id = v_branch AND b.tenant_id = p_tenant_id AND b.unit_type = 'branch'
      AND b.is_active = true AND x.user_id = v_actor
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.edu_can_access_attendance_enrollment(p_tenant_id uuid, p_enrollment_id uuid, p_school_day date)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  v_actor uuid;
  v_role text;
  v_product text;
  v_course uuid;
  v_branch uuid;
  v_binding_count bigint;
BEGIN
  IF current_setting('role', true) = 'service_role' THEN RETURN true; END IF;
  IF current_setting('role', true) IS DISTINCT FROM 'authenticated' THEN RETURN false; END IF;

  v_actor := auth.uid();
  IF v_actor IS NULL OR p_tenant_id IS NULL OR p_enrollment_id IS NULL OR p_school_day IS NULL THEN
    RETURN false;
  END IF;

  SELECT u.role, t.product_key INTO v_role, v_product
  FROM auth.users a
  JOIN public.users u ON u.id = a.id
  JOIN public.tenants t ON t.id = u.tenant_id
  WHERE u.id = v_actor
    AND u.tenant_id = p_tenant_id
    AND a.deleted_at IS NULL
    AND (a.banned_until IS NULL OR a.banned_until <= clock_timestamp())
    AND u.status = 'active'
    AND t.status = 'active';
  IF NOT FOUND OR v_product IS NULL THEN RETURN false; END IF;

  SELECT e.course_id INTO v_course
  FROM public.edu_enrollments e
  JOIN public.edu_courses c ON c.id = e.course_id AND c.tenant_id = e.tenant_id
  WHERE e.id = p_enrollment_id AND e.tenant_id = p_tenant_id;
  IF NOT FOUND THEN RETURN false; END IF;

  -- Preserve existing tenant-scoped behavior for other Education products.
  IF v_product <> 'bella_preschool' THEN RETURN true; END IF;

  -- Preschool attendance requires an active administrator and today's school day.
  -- Teacher authorization stays closed until a canonical Auth-to-branch confirmation exists.
  IF v_role <> 'admin'
    OR p_school_day <> (clock_timestamp() AT TIME ZONE 'Asia/Ho_Chi_Minh')::date THEN
    RETURN false;
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.edu_enrollments e
    JOIN public.edu_courses c ON c.id = e.course_id AND c.tenant_id = e.tenant_id
    WHERE e.id = p_enrollment_id
      AND e.tenant_id = p_tenant_id
      AND e.course_id = v_course
      AND e.status = 'active'
      AND c.status = 'active'
      AND e.enrolled_at < ((p_school_day + 1)::timestamp AT TIME ZONE 'Asia/Ho_Chi_Minh')
  ) THEN RETURN false; END IF;

  SELECT count(*), (array_agg(a.branch_id))[1]
  INTO v_binding_count, v_branch
  FROM public.preschool_chain_course_branch_assignments a
  WHERE a.tenant_id = p_tenant_id AND a.course_id = v_course;
  IF v_binding_count <> 1 OR v_branch IS NULL THEN RETURN false; END IF;

  RETURN EXISTS (
    SELECT 1
    FROM public.org_units b
    JOIN public.user_org_unit_access a ON a.org_unit_id = b.id AND a.tenant_id = b.tenant_id
    WHERE b.id = v_branch
      AND b.tenant_id = p_tenant_id
      AND b.unit_type = 'branch'
      AND b.is_active
      AND a.user_id = v_actor
      AND a.relationship_id IS NOT NULL
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.edu_set_scoped_daily_attendance(p_tenant_id uuid, p_actor_id uuid, p_expected_role text, p_branch_id uuid, p_enrollment_id uuid, p_course_id uuid, p_student_party_id uuid, p_request_id text, p_status text, p_roll_call_time timestamp with time zone, p_school_day date)
 RETURNS TABLE(id uuid, tenant_id uuid, enrollment_id uuid, school_day date, status text, event_id uuid, roll_call_time timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_enrollment public.edu_enrollments%ROWTYPE; v_role text;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' OR p_actor_id IS NULL
    OR (auth.uid() IS NOT NULL AND auth.uid() IS DISTINCT FROM p_actor_id) THEN
    RAISE EXCEPTION 'ATTENDANCE_TRUSTED_ACTOR_REQUIRED' USING ERRCODE='42501';
  END IF;
  IF p_tenant_id IS NULL OR p_branch_id IS NULL OR p_enrollment_id IS NULL OR p_course_id IS NULL
    OR p_student_party_id IS NULL OR p_request_id IS NULL OR p_expected_role IS NULL
    OR p_status IS NULL OR p_status NOT IN ('present','absent','excused')
    OR p_school_day IS NULL OR p_roll_call_time IS NULL
    OR (p_roll_call_time AT TIME ZONE 'Asia/Ho_Chi_Minh')::date IS DISTINCT FROM p_school_day THEN
    RAISE EXCEPTION 'ATTENDANCE_SCOPED_INPUT_INVALID' USING ERRCODE='22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('education-attendance:'||p_tenant_id::text||':'||p_enrollment_id::text||':'||p_school_day::text,0));
  SELECT e.* INTO v_enrollment FROM public.edu_enrollments e
    WHERE e.id=p_enrollment_id AND e.tenant_id=p_tenant_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ATTENDANCE_ENROLLMENT_DENIED' USING ERRCODE='42501'; END IF;
  -- Acquire an existing daily row's write lock before the final authority read.
  -- The common advisory lock serializes absent-row inserts by daily RPC writers.
  PERFORM 1 FROM public.edu_attendance_daily_state s WHERE s.tenant_id=p_tenant_id
    AND s.enrollment_id=p_enrollment_id AND s.school_day=p_school_day FOR UPDATE;
  -- Take all known write/FK waits before current actor/branch validation.
  LOCK TABLE public.edu_attendance,public.edu_attendance_daily_state IN ROW EXCLUSIVE MODE;
  PERFORM 1 FROM public.tenants t WHERE t.id=p_tenant_id FOR KEY SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ATTENDANCE_CURRENT_TENANT_DENIED' USING ERRCODE='42501'; END IF;
  IF v_enrollment.course_id IS DISTINCT FROM p_course_id OR v_enrollment.student_party_id IS DISTINCT FROM p_student_party_id
    OR v_enrollment.request_id IS DISTINCT FROM p_request_id THEN
    RAISE EXCEPTION 'ATTENDANCE_CANONICAL_CONFLICT' USING ERRCODE='23505';
  END IF;
  -- Keep reconciled canonical rows stable through any later branch-row wait.
  PERFORM 1 FROM public.edu_courses c WHERE c.id=p_course_id AND c.tenant_id=p_tenant_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ATTENDANCE_CANONICAL_CONFLICT' USING ERRCODE='23505'; END IF;
  PERFORM 1 FROM public.party_parties p WHERE p.id=p_student_party_id AND p.tenant_id=p_tenant_id
    AND p.party_type='person' AND p.deleted_at IS NULL FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ATTENDANCE_CANONICAL_CONFLICT' USING ERRCODE='23505'; END IF;
  PERFORM public.platform_assert_active_branch_for_actor(p_tenant_id,p_actor_id,p_branch_id);
  SELECT lower(btrim(u.role)) INTO v_role FROM auth.users a JOIN public.users u ON u.id=a.id
    JOIN public.tenants t ON t.id=u.tenant_id WHERE a.id=p_actor_id AND a.deleted_at IS NULL
    AND (a.banned_until IS NULL OR a.banned_until<=clock_timestamp())
    AND u.tenant_id=p_tenant_id AND u.status='active' AND t.status='active';
  IF v_role IS NULL OR v_role IS DISTINCT FROM lower(btrim(p_expected_role)) THEN
    RAISE EXCEPTION 'ATTENDANCE_CURRENT_ACTOR_ROLE_DENIED' USING ERRCODE='42501';
  END IF;

  RETURN QUERY SELECT * FROM public.edu_set_daily_attendance(p_tenant_id,p_enrollment_id,p_status,p_roll_call_time,p_school_day);
END;
$function$

CREATE OR REPLACE FUNCTION public.party_resolve_current_auth_link()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE c record; r public.party_auth_links%ROWTYPE;
BEGIN
  SELECT * INTO c FROM public.party_auth_link_context(false,false);
  SELECT l.* INTO r FROM public.party_auth_links l JOIN public.party_parties p ON p.id=l.party_id AND p.tenant_id=l.tenant_id
    WHERE l.auth_user_id=c.actor_id AND l.tenant_id=c.tenant_id AND l.revoked_at IS NULL
      AND l.valid_from<=clock_timestamp() AND (l.valid_until IS NULL OR l.valid_until>clock_timestamp())
      AND p.party_type='person' AND p.deleted_at IS NULL AND btrim(p.display_name)<>'';
  IF NOT FOUND THEN RETURN NULL; END IF;
  RETURN jsonb_build_object('id',r.id,'tenantId',r.tenant_id,'authUserId',r.auth_user_id,
    'partyId',r.party_id,'validFrom',r.valid_from,'validUntil',r.valid_until);
END;
$function$

CREATE OR REPLACE FUNCTION public.preschool_branch_access(p_tenant_id uuid, p_actor_id uuid, p_branch_id uuid, p_action text DEFAULT 'registry'::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'pg_temp'
AS $function$
DECLARE v_role text; v_allowed boolean;
BEGIN
  IF p_actor_id IS NULL OR (auth.role() IS DISTINCT FROM 'service_role' AND auth.uid() IS DISTINCT FROM p_actor_id) THEN RETURN false; END IF;
  SELECT lower(u.role) INTO v_role FROM public.users u JOIN public.tenants t ON t.id=u.tenant_id
    JOIN auth.users a ON a.id=u.id WHERE u.id=p_actor_id AND u.tenant_id=p_tenant_id
      AND u.status='active' AND t.status='active';
  IF v_role IS NULL OR (p_action='admission' AND v_role NOT IN ('admin','super_admin'))
    OR (p_action IN ('registry','attendance') AND v_role NOT IN ('admin','super_admin','admin_staff'))
    OR p_action IS NULL OR p_action NOT IN ('admission','registry','attendance') THEN RETURN false; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.org_units WHERE id=p_branch_id AND tenant_id=p_tenant_id
    AND unit_type='branch' AND is_active=true) THEN RETURN false; END IF;
  IF auth.role()='service_role' THEN
    RETURN v_role IN ('admin','super_admin');
  END IF;
  SELECT EXISTS(SELECT 1 FROM public.user_org_unit_access WHERE user_id=auth.uid()
    AND tenant_id=p_tenant_id AND org_unit_id=p_branch_id) INTO v_allowed;
  RETURN v_allowed;
END;
$function$

CREATE OR REPLACE FUNCTION public.preschool_set_scoped_daily_attendance(p_tenant_id uuid, p_actor_id uuid, p_expected_role text, p_branch_id uuid, p_enrollment_id uuid, p_course_id uuid, p_student_party_id uuid, p_status text, p_roll_call_time timestamp with time zone, p_school_day date)
 RETURNS TABLE(id uuid, tenant_id uuid, enrollment_id uuid, school_day date, status text, event_id uuid, roll_call_time timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_course public.preschool_chain_course_branch_assignments%ROWTYPE;
  v_assignment public.preschool_chain_enrollment_branch_assignments%ROWTYPE;
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' OR p_actor_id IS NULL
    OR p_expected_role IS NULL OR lower(btrim(p_expected_role)) NOT IN ('admin','super_admin','admin_staff') THEN
    RAISE EXCEPTION 'PRESCHOOL_ATTENDANCE_ACTION_DENIED' USING ERRCODE='42501';
  END IF;
  SELECT a.* INTO v_course FROM public.preschool_chain_course_branch_assignments a
    WHERE a.tenant_id=p_tenant_id AND a.course_id=p_course_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'PRESCHOOL_ATTENDANCE_COURSE_DENIED' USING ERRCODE='42501'; END IF;
  SELECT a.* INTO v_assignment FROM public.preschool_chain_enrollment_branch_assignments a
    WHERE a.tenant_id=p_tenant_id AND a.enrollment_id=p_enrollment_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'PRESCHOOL_ATTENDANCE_ENROLLMENT_DENIED' USING ERRCODE='42501'; END IF;
  IF v_assignment.course_id IS DISTINCT FROM p_course_id OR v_assignment.branch_id IS DISTINCT FROM p_branch_id
    OR v_course.branch_id IS DISTINCT FROM p_branch_id THEN
    RAISE EXCEPTION 'PRESCHOOL_ATTENDANCE_CANONICAL_CONFLICT' USING ERRCODE='23505';
  END IF;
  RETURN QUERY SELECT * FROM public.edu_set_scoped_daily_attendance(p_tenant_id,p_actor_id,p_expected_role,p_branch_id,
    p_enrollment_id,p_course_id,p_student_party_id,v_assignment.request_id::text,p_status,p_roll_call_time,p_school_day);
END;
$function$

CREATE OR REPLACE FUNCTION public.preschool_teacher_assert_admin(p_tenant_id uuid, p_actor_id uuid, p_branch_id uuid, p_course_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role' OR p_tenant_id IS NULL OR p_actor_id IS NULL
    OR p_branch_id IS NULL OR (auth.uid() IS NOT NULL AND auth.uid() IS DISTINCT FROM p_actor_id)
  THEN RAISE EXCEPTION 'PRESCHOOL_TEACHER_ACCESS_DENIED' USING ERRCODE='42501'; END IF;
  IF current_setting('transaction_isolation')<>'read committed'
  THEN RAISE EXCEPTION 'PRESCHOOL_TEACHER_READ_COMMITTED_REQUIRED' USING ERRCODE='40001'; END IF;
  PERFORM 1 FROM public.users u JOIN auth.users a ON a.id=u.id
    JOIN public.tenants t ON t.id=u.tenant_id
    WHERE u.id=p_actor_id AND u.tenant_id=p_tenant_id AND u.status='active' AND u.role='admin'
      AND t.status='active' AND t.product_key='bella_preschool' AND a.deleted_at IS NULL
      AND (a.banned_until IS NULL OR a.banned_until<=clock_timestamp()) FOR SHARE OF u,a,t;
  IF NOT FOUND THEN RAISE EXCEPTION 'PRESCHOOL_TEACHER_ACCESS_DENIED' USING ERRCODE='42501'; END IF;
  PERFORM public.platform_assert_active_branch_for_actor(p_tenant_id,p_actor_id,p_branch_id);
  IF p_course_id IS NOT NULL THEN
    PERFORM 1 FROM public.edu_courses c JOIN public.preschool_chain_course_branch_assignments m
      ON m.course_id=c.id AND m.tenant_id=c.tenant_id
      WHERE c.id=p_course_id AND c.tenant_id=p_tenant_id AND m.branch_id=p_branch_id FOR SHARE OF c,m;
    IF NOT FOUND THEN RAISE EXCEPTION 'PRESCHOOL_TEACHER_COURSE_DENIED' USING ERRCODE='42501'; END IF;
  END IF;
END $function$
